{
  "a_sentences": [
    {
      "a_text": "Le Tribunal fédéral rappelle que les dispositions et principes relatifs à l'invalidité, à l'incapacité de travail et au droit à la rente selon la LPGA et la LAI, ainsi que la jurisprudence sur la valeur probante et l'appréciation des rapports et expertises médicaux, ont été correctement exposés par la juridiction cantonale.",
      "b_propositions": ["P1", "P3"]
    },
    {
      "a_text": "Il précise également que les règles de révision s'appliquent par analogie aux nouvelles demandes.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que le recourant ne démontre pas de violation du droit fédéral par l'autorité précédente.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que l'autorité précédente n'a pas violé le droit fédéral en accordant pleine valeur probante à l'expertise ABI du 28 novembre 2023 et en retenant une capacité de travail de 80 % du recourant.",
      "b_propositions": ["P8"]
    },
    {
      "a_text": "Le Tribunal fédéral indique qu'il n'est pas nécessaire que la juridiction cantonale examine en détail tous les arguments et réponde explicitement à chaque grief.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Il ajoute qu'il n'est donc pas utile de discuter davantage de l'examen autonome des indicateurs par le recourant.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que les conditions pour des mesures d'ordre professionnel ne sont pas remplies.",
      "b_propositions": ["P4"]
    }
  ]
}
